-- BOWMASTERS
-- Do not edit this file. Any change breaks the decoder.
local _dqnnlc = 35
local _qvrbfj = 178
local _ebdtlz = 160
local _mzwadb = ""

local _iwooiy = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _vfbysj(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _glenqj(d)
	d = d:gsub("[^" .. _iwooiy .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_iwooiy:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _kplqxt = _glenqj(_mzwadb)
local _ftlfpr = { _dqnnlc, _qvrbfj, _ebdtlz }
local _oystel = {}
for i = 1, #_kplqxt do
	_oystel[i] = string.char(_vfbysj(_kplqxt:byte(i), _ftlfpr[(i - 1) % 3 + 1]))
end

local _ygxikx = load or loadstring
local _pkagnh, _rzpioy = _ygxikx(table.concat(_oystel), "=w")
if not _pkagnh then
	gg.alert("Corrupted file: " .. tostring(_rzpioy))
	os.exit()
end
_pkagnh()
